const http2 = require('http2');
const fs = require('fs');
const jwt = require('jsonwebtoken');
const { StudentRecordDb } = require('../models/students');

const server = http2.createSecureServer({
  key: fs.readFileSync('/etc/ssl/university.key'),
  cert: fs.readFileSync('/etc/ssl/university.crt')
});

server.on('stream', async (stream, headers) => {
  const url = new URL(headers[':path'], 'https://registrar.university.internal');

  if (url.pathname === '/student/portal') {
    const studentId = url.searchParams.get('studentId');

    const authHeader = headers['authorization'];
    if (!authHeader) {
      stream.respond({ ':status': 401 });
      return stream.end('Unauthorized');
    }

    let user;
    try {
      user = jwt.verify(authHeader.replace('Bearer ', ''), process.env.JWT_SECRET);
    } catch {
      stream.respond({ ':status': 401 });
      return stream.end('Invalid credentials');
    }

    // Verify caller is either the student themselves or a registered academic advisor
    if (user.studentId !== studentId && user.role !== 'ACADEMIC_ADVISOR') {
      stream.respond({ ':status': 403 });
      return stream.end('Access denied: unauthorized to inspect this student transcript');
    }

    if (studentId && stream.pushAllowed) {
      stream.pushStream({ ':path': `/api/transcripts/${studentId}/gpa.json` }, async (err, pushStream) => {
        if (err) return;
        const transcript = await StudentRecordDb.getStudentTranscript(studentId);
        pushStream.respond({ ':status': 200, 'content-type': 'application/json' });
        pushStream.end(JSON.stringify(transcript));
      });
    }

    stream.respond({ ':status': 200, 'content-type': 'text/html' });
    stream.end('<html><body>Student portal loaded</body></html>');
  }
});

server.listen(8448);
